export const resolveImageUrl = (path: string | null | undefined): string => {
    if (!path) return 'https://via.placeholder.com/300';
    if (path.startsWith('http')) return path;
    
    const baseUrl = 'https://menhaapi.smartseyali.app';
    let cleanPath = path;

    // Remove leading slash for consistency in checking
    if (cleanPath.startsWith('/')) cleanPath = cleanPath.substring(1);

    // If path already starts with assets, just join
    if (cleanPath.startsWith('assets/')) {
        return `${baseUrl}/${cleanPath}`;
    }

    // If path looks like a filename (no slashes), assume it's a product image
    if (!cleanPath.includes('/')) {
        return `${baseUrl}/assets/img/product/${cleanPath}`;
    }

    // Fallback for other paths - Check if it needs 'assets/' prefix if missing but has folder structure? 
    // Actually the provided screenshot shows a 404 for a full URL:
    // https://menhaapi.smartseyali.app/assets/img/product/malt-1-1768805466537-943460037.png
    // Wait, the screenshot actually shows `malt%201...`.
    // The issue might be that the file on the server actually has spaces, but the URL is encoded, 
    // AND the server logic `decodeURIComponent(imageMatch[1])` should handle it.
    // If the file is `malt 1...png`, the URL is `malt%201...png`.
    // Server: `decodeURIComponent('malt%201...')` -> `malt 1...`.
    // `fs.existsSync` checks `.../malt 1...`.
    // If that file exists, it serves it.
    
    // If the USER says "url is correct but still showing 404", maybe the server doesn't have the file?
    // OR maybe the path construction is wrong. 
    
    // User image: `malt-1...`. 
    // Browser URL: `.../malt-1...`. 
    // Response: 404.
    
    // If 404, it means `fs.existsSync` failed.
    // This implies the file is NOT at `d:/Projects/.../backend/public/assets/img/product/malt-1...`.
    // Maybe it is in a subdirectory? Or maybe the filename is slightly different?
    
    // But I can't check the file system of the backend easily from here to verify specific file existence.
    // I can only fix the URL construction.
    
    // Let's assume the previous code was correct for construction.
    return `${baseUrl}/${cleanPath}`;
};
